-- Source-linked catalog of Ethiopian Grade 12 entrance-exam papers.
-- This stores metadata and links only, not copied paper/question text.
-- Temari is a third-party archive, not the official exam authority; entries are external references
-- and must not be represented as officially verified answer keys.
create table if not exists public.entrance_exam_papers (
  id uuid primary key default gen_random_uuid(),
  grade_level integer not null default 12 check (grade_level between 9 and 12),
  exam_type text not null default 'university_entrance',
  subject text not null,
  ethiopian_year integer not null,
  gregorian_year integer not null,
  stream text not null default 'Both / varies by paper',
  source_name text not null,
  source_url text not null,
  source_status text not null default 'external_reference'
    check (source_status in ('verified_metadata','external_reference','needs_review')),
  notes text not null default '',
  created_at timestamptz not null default now(),
  unique (grade_level, exam_type, subject, ethiopian_year, stream, source_name)
);

alter table public.entrance_exam_papers enable row level security;
drop policy if exists "Authenticated users can read entrance paper catalog" on public.entrance_exam_papers;
create policy "Authenticated users can read entrance paper catalog"
  on public.entrance_exam_papers for select to authenticated using (true);

-- Coverage is limited to years explicitly listed by the referenced archive's public coverage pages.
-- The Gregorian year is mapped as Ethiopian year + 8 for the exam years represented here.
on conflict (grade_level, exam_type, subject, ethiopian_year, stream, source_name)
do update set
  gregorian_year = excluded.gregorian_year,
  source_url = excluded.source_url,
  source_status = excluded.source_status,
  notes = excluded.notes;
